refentry.refsect1:
&reftitle.errors;
Функция выбрасывает ошибку ValueError, если значение параметра insertion_cost, replacement_cost или deletion_cost меньше или равно 0.
Функция возвращает &false; и устанавливает ошибку intl, если одна из входных строк некорректна в кодировке UTF-8, если значение параметра locale — некорректный идентификатор локали или если произошла внутренняя ошибка библиотеки ICU.

  &reftitle.examples;

   Пример использования функции grapheme_levenshtein


<?php

// Составная форма (NFC): U+00E9 LATIN SMALL LETTER E WITH ACUTE
$e_composed = "\u{00E9}";

// Разложенная форма (NFD): U+0065 + U+0301 (e + комбинируемый акут)
$e_decomposed = "\u{0065}\u{0301}";

// Функция grapheme_levenshtein считает их одним и тем же кластером графем
var_dump(grapheme_levenshtein($e_composed, $e_decomposed));

// Функция levenshtein() работает с байтами и видит их как разные
var_dump(levenshtein($e_composed, $e_decomposed));

?>


   &example.outputs;


int(0)
int(3)

